:root {
  /* Backgrounds */
  --bg-base: #0A0A0A;
  --bg-card: #131313;
  --bg-card-elevated: #1C1C1C;
  --bg-overlay: rgba(28,28,28,0.95);

  /* Accent */
  --accent: #D4A843;
  --accent-dark: #B8902F;
  --accent-subtle: rgba(212,168,67,0.12);

  /* Text */
  --text-primary: #F5F5F5;
  --text-secondary: #8A8A8A;
  --text-tertiary: #555555;

  /* Semantic */
  --success: #4CAF50;
  --warning: #FF7043;
  --danger: #EF5350;

  /* Borders */
  --border-subtle: #1F1F1F;

  /* Radius */
  --radius-card: 14px;
  --radius-pill: 50px;
  --radius-sm: 8px;

  /* Spacing */
  --space-page: 20px;
  --space-card-h: 20px;
  --space-card-v: 16px;
  --gap-card: 10px;
  --gap-section: 28px;

  /* Typography */
  --font: 'Inter', -apple-system, sans-serif;
  --size-display: 48px;
  --size-h1: 24px;
  --size-h2: 17px;
  --size-body: 15px;
  --size-caption: 12px;
  --size-micro: 11px;
}
